// ==========================================
// EIK & BG VAT Validation Helper Functions
// ==========================================

/**
 * Validates 9-digit Bulgarian EIK checksum.
 */
export function validateEik9(eik) {
  if (!eik || typeof eik !== 'string') return false;
  const clean = eik.trim();
  if (clean.length !== 9 || !/^\d{9}$/.test(clean) || /^0+$/.test(clean)) return false;

  const digits = clean.split('').map(Number);
  const w1 = [1, 2, 3, 4, 5, 6, 7, 8];
  const s1 = w1.reduce((acc, w, i) => acc + w * digits[i], 0);
  const r1 = s1 % 11;
  if (r1 < 10) return digits[8] === r1;

  const w2 = [3, 4, 5, 6, 7, 8, 9, 10];
  const s2 = w2.reduce((acc, w, i) => acc + w * digits[i], 0);
  const r2 = s2 % 11;
  if (r2 < 10) return digits[8] === r2;
  return digits[8] === 0;
}

/**
 * Validates 10-digit Bulgarian EGN checksum.
 */
export function validateEgn10(egn) {
  if (!egn || typeof egn !== 'string') return false;
  const clean = egn.trim();
  if (clean.length !== 10 || !/^\d{10}$/.test(clean) || /^0+$/.test(clean)) return false;

  const digits = clean.split('').map(Number);
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  const s = weights.reduce((acc, w, i) => acc + w * digits[i], 0);
  const r = s % 11;
  const expected = r < 10 ? r : 0;
  return digits[9] === expected;
}

/**
 * Validates 13-digit Bulgarian branch EIK checksum.
 */
export function validateEik13(eik) {
  if (!eik || typeof eik !== 'string') return false;
  const clean = eik.trim();
  if (clean.length !== 13 || !/^\d{13}$/.test(clean) || /^0+$/.test(clean)) return false;
  if (!validateEik9(clean.substring(0, 9))) return false;

  const digits = clean.split('').map(Number);
  const w1 = [2, 7, 3, 5];
  const s1 = w1.reduce((acc, w, i) => acc + w * digits[8 + i], 0);
  const r1 = s1 % 11;
  if (r1 < 10) return digits[12] === r1;

  const w2 = [4, 9, 5, 7];
  const s2 = w2.reduce((acc, w, i) => acc + w * digits[8 + i], 0);
  const r2 = s2 % 11;
  if (r2 < 10) return digits[12] === r2;
  return digits[12] === 0;
}

/**
 * Universal EIK/EGN Validator (9, 10, or 13 digits).
 */
export function validateEik(input) {
  if (!input) return false;
  let clean = String(input).trim().replace(/[\s\.\-]/g, '');
  if (clean.toUpperCase().startsWith('BG')) clean = clean.substring(2);

  if (clean.length === 9) return validateEik9(clean);
  if (clean.length === 10) return validateEgn10(clean) || validateEik9(clean);
  if (clean.length === 13) return validateEik13(clean);
  return false;
}

/**
 * BG VAT Validator (Prefix 'BG' + 9/10/13 digit EIK/EGN).
 */
export function validateVat(input) {
  if (!input) return false;
  const clean = String(input).trim().replace(/[\s\.\-]/g, '');
  if (!clean.toUpperCase().startsWith('BG')) return false;
  return validateEik(clean.substring(2));
}

/**
 * Financial Totals Rounding Checker (Tolerance <= 0.02 BGN).
 */
export function verifyFinancialTotals(taxBase, vatAmount, totalAmount) {
  const tb = Number(taxBase) || 0;
  const vat = Number(vatAmount) || 0;
  const tot = Number(totalAmount) || 0;

  const expectedTotal = Math.round((tb + vat) * 100) / 100;
  const diff = Math.abs(Math.round((tb + vat - tot) * 10000) / 10000);
  const isValid = diff <= 0.02;

  return {
    isValid,
    difference: diff,
    taxBase: Math.round(tb * 100) / 100,
    vatAmount: Math.round(vat * 100) / 100,
    expectedTotal,
    actualTotal: Math.round(tot * 100) / 100
  };
}

/**
 * Defensive Client Fallback Parser for OCR Extraction Results.
 * Handles missing/null values gracefully and builds a sanitized invoice structure.
 */
export function parseOcrResponse(data) {
  if (!data || typeof data !== 'object') {
    return {
      status: 'INVALID',
      invoice_number: '0000000000',
      invoice_date: new Date().toLocaleDateString('bg-BG'),
      currency: 'BGN',
      supplier_name: 'Неизвестен доставчик',
      supplier_eik: '',
      supplier_vat: '',
      recipient_name: 'Неизвестен получател',
      recipient_eik: '',
      recipient_vat: '',
      tax_base: 0,
      vat_amount: 0,
      total_amount: 0,
      line_items: [],
      validation_details: {
        supplier_eik_valid: false,
        supplier_vat_valid: false,
        recipient_eik_valid: false,
        recipient_vat_valid: false,
        financial_totals_valid: false,
        rounding_difference: 0
      },
      validation_errors: ['Невалиден или празен отговор от OCR сървъра'],
      raw: data || {}
    };
  }

  const supEik = String(data.supplier_eik || '').trim();
  const recEik = String(data.recipient_eik || '').trim();
  const supVat = String(data.supplier_vat || (supEik ? `BG${supEik}` : '')).trim().toUpperCase();
  const recVat = String(data.recipient_vat || (recEik ? `BG${recEik}` : '')).trim().toUpperCase();

  const taxBase = Number(data.tax_base) || 0;
  const vatAmount = Number(data.vat_amount) || 0;
  const totalAmount = Number(data.total_amount) || 0;

  const supEikValid = data.validation_details?.supplier_eik_valid ?? validateEik(supEik);
  const supVatValid = data.validation_details?.supplier_vat_valid ?? validateVat(supVat);
  const recEikValid = data.validation_details?.recipient_eik_valid ?? (recEik ? validateEik(recEik) : true);
  const recVatValid = data.validation_details?.recipient_vat_valid ?? (recVat ? validateVat(recVat) : true);

  const finCheck = verifyFinancialTotals(taxBase, vatAmount, totalAmount);

  const rawItems = Array.isArray(data.line_items) ? data.line_items : [];
  const lineItems = rawItems.map((item, idx) => ({
    id: idx + 1,
    description: String(item?.description || item?.name || `Артикул / Услуга #${idx + 1}`),
    quantity: Number(item?.quantity) || 1,
    unit_price: Number(item?.unit_price || item?.price) || 0,
    total_price: Number(item?.total_price || item?.total) || 0
  }));

  const isValidated = supEikValid && supVatValid && recEikValid && recVatValid && finCheck.isValid;
  const defaultStatus = isValidated ? 'VALIDATED' : 'INVALID';

  return {
    status: String(data.status || defaultStatus),
    invoice_number: String(data.invoice_number || '0000000000'),
    invoice_date: String(data.invoice_date || new Date().toLocaleDateString('bg-BG')),
    currency: String(data.currency || 'BGN'),
    supplier_name: String(data.supplier_name || 'Неизвестен доставчик'),
    supplier_eik: supEik,
    supplier_vat: supVat,
    recipient_name: String(data.recipient_name || 'Неизвестен получател'),
    recipient_eik: recEik,
    recipient_vat: recVat,
    tax_base: taxBase,
    vat_amount: vatAmount,
    total_amount: totalAmount,
    line_items: lineItems.length > 0 ? lineItems : [
      {
        id: 1,
        description: 'Основна доставка / Услуга',
        quantity: 1,
        unit_price: taxBase || totalAmount,
        total_price: taxBase || totalAmount
      }
    ],
    validation_details: {
      supplier_eik_valid: supEikValid,
      supplier_vat_valid: supVatValid,
      recipient_eik_valid: recEikValid,
      recipient_vat_valid: recVatValid,
      financial_totals_valid: finCheck.isValid,
      rounding_difference: finCheck.difference
    },
    validation_errors: data.validation_errors && Array.isArray(data.validation_errors) && data.validation_errors.length > 0
      ? data.validation_errors
      : (isValidated ? [] : [
          ...(!supEikValid ? [`Невалиден ЕИК на доставчик: ${supEik || 'липсва'}`] : []),
          ...(!supVatValid ? [`Невалиден ДДС № на доставчик: ${supVat || 'липсва'}`] : []),
          ...(!finCheck.isValid ? [`Финансово закръгление извън толеранс (различие: ${finCheck.difference} лв.)`] : [])
        ]),
    raw: data
  };
}


